      health: 100,
      maxHealth: 100,
      alive: true,
      fall: 0,
      path: [],
      pathIndex: 0,
      state: 'roam', // 'roam', 'combat', 'plant', 'defuse', 'cover'
      targetEnemy: null,
      aimTimer: 0,
      burstTimer: 0,
      ammo: 30,
      homePos: cfg.pos.clone(),
      objectiveTarget: isAttack ? new THREE.Vector3(-13, 0, -14) : new THREE.Vector3(0, 0, 15), // Attackers go to Site A, Defenders hold mid/site
